stepxmp.pre:
note {
    display: block;
    position: relative;
}
note > tag {
    position: absolute;
    top: 0;
    right: 0;
}

article {
    display: block;
    position: relative;
}
article > stripe {
    position: absolute;
    top: 0;
    left: 0;
    width: 4pt;
    height: 100%;
    background: navy;
}

banner {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    height: 18pt;
    background: #c81e00;
    color: white;
}
guide {
    display: block;
    padding-top: 26pt;
    box-decoration-break: clone;
}

stamp {
    position: absolute;
    inset: 0;
    width: 60pt;
    height: 20pt;
    justify-self: end;
    align-self: center;
}

figure {
    display: block;
    anchor-name: --figure;
}
callout {
    position: absolute;
    top: anchor(--figure bottom);
    left: anchor(--figure 25%, 12pt);
    width: anchor-size(--figure width);
}

tooltip {
    position: absolute;
    position-anchor: --term;
    position-area: top center;
}

@position-try --left-side {
    position-area: left center;
    margin-right: 4pt;
}
note {
    position: absolute;
    position-anchor: --mark;
    position-area: right center;
    position-try-fallbacks: flip-inline, --left-side;
}

arrow {
    position: fixed;
    position-anchor: --sign;
    position-area: bottom center;
    position-visibility: anchors-valid;
}

guide { writing-mode: vertical-rl; }
seal {
    position: fixed;
    inset-block-start: 0;
    inset-inline-start: 0;
}
